import base64
import hashlib
import os
import json
from PIL import Image

def decode(name, n, sha, b64):
    raw = base64.b64decode(b64)
    assert len(raw) == n, (name, len(raw), n)
    assert hashlib.sha256(raw).hexdigest() == sha, name
    path = f'/tmp/{name}'
    open(path,'wb').write(raw)
    return path

def stitch(existing, extras, out_path, expect_w, expect_h):
    row0 = Image.open(existing).convert('RGBA')
    assert row0.size[1] == 64, row0.size
    parts = [row0] + [Image.open(p).convert('RGBA') for p in extras]
    w = parts[0].size[0]
    assert all(p.size == (w, 64) for p in parts), [p.size for p in parts]
    out = Image.new('RGBA', (w, 64 * len(parts)))
    for i, p in enumerate(parts):
        out.paste(p, (0, i * 64))
    assert out.size == (expect_w, expect_h), out.size
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    out.save(out_path, 'PNG')
    print(out_path, out.size, os.path.getsize(out_path))

